$ErrorActionPreference='Stop';$root='__ROOT__';$id='__ID__';$task='__TASK__';$backup=$task+'-Backup';$agent='C:\Program Files\RoutePilot\Agent'
if((Get-CimInstance Win32_ComputerSystemProduct).UUID -ne 'F8798200-12FB-11F1-8F47-A104BEE59100'){throw 'Wrong station'}
for($i=0;$i -lt 500 -and !(Test-Path -LiteralPath "$root\result-backup.json");$i++){Start-Sleep -Milliseconds 100}
if(!(Test-Path -LiteralPath "$root\result-backup.json")){throw 'Backup recovery result unavailable'}
$result=[IO.File]::ReadAllText("$root\result-backup.json")|ConvertFrom-Json;$baseline=[IO.File]::ReadAllText("$root\baseline.json")|ConvertFrom-Json;$stopped=[IO.File]::ReadAllText("$root\stopped.json")|ConvertFrom-Json
$retired=[IO.File]::ReadAllText("$root\retired-backup.json")|ConvertFrom-Json
if($retired.run -cne $id -or $retired.role -cne 'backup' -or !$retired.controllerStopped -or $retired.jobActiveAfter -ne 0){throw 'Actor job retirement unconfirmed'}
if($result.run -cne $id -or $result.role -cne 'backup' -or !$result.success -or $result.jobActiveAfter -ne 0 -or $stopped.run -cne $id -or !$stopped.oldStopped -or !$stopped.nativeStartRefusedWhileIntentWriteDenied -or $stopped.oldPid -ne $baseline.servicePid){throw 'Recovery evidence differs'}
$svc=Get-CimInstance Win32_Service -Filter "Name='RoutePilotRescue'";$actual='C:\Users\CITASTATION\AppData\Local\Programs\CITA Route\client';$intentPath=Join-Path $agent 'native\intent.json';$intent=[IO.File]::ReadAllText($intentPath)|ConvertFrom-Json
if(!$svc -or $svc.State -ne 'Running' -or $svc.ProcessId -ne $result.servicePid -or $svc.ProcessId -eq $baseline.servicePid -or $intent.Desired -isnot [bool] -or $intent.Desired -or $intent.Operation -cne $baseline.operation -or $intent.Generation -ne $baseline.generation -or (Get-FileHash -LiteralPath $intentPath).Hash -cne $baseline.intentSha -or (Get-FileHash -LiteralPath (Join-Path $agent 'RoutePilot.Agent.exe')).Hash -cne $baseline.agentSha -or (Get-FileHash -LiteralPath (Join-Path $actual 'manifest.json')).Hash -cne $baseline.manifestSha){throw 'Recovered service or baseline differs'}
foreach($name in @($task,$backup)){$definition=Get-ScheduledTask -TaskName $name -ErrorAction Stop;$principal=[string]$definition.Principal.UserId;$sid=if($principal -match '^S-1-'){$principal}else{([Security.Principal.NTAccount]::new($principal)).Translate([Security.Principal.SecurityIdentifier]).Value};$role=if($name -eq $task){'--primary'}else{'--backup'};if($sid -ne 'S-1-5-18' -or $definition.Actions.Count -ne 1 -or $definition.Actions[0].Execute -ine "$root\Cita.PhysicalServiceCycle.exe" -or $definition.Actions[0].Arguments -ne ($role+' "'+$root+'"')){throw 'Watcher task identity differs'}}
for($i=0;$i -lt 50 -and (Get-ScheduledTask -TaskName $backup).State -eq 'Running';$i++){Start-Sleep -Milliseconds 100}
if((Get-ScheduledTask -TaskName $backup).State -eq 'Running' -or (Get-ScheduledTaskInfo -TaskName $backup).LastTaskResult -ne 0){throw 'Backup watcher did not finish'}
if(@(Get-CimInstance Win32_Process|Where-Object {$_.ProcessId -ne $PID -and (($_.ExecutablePath -and $_.ExecutablePath.StartsWith($root+'\',[StringComparison]::OrdinalIgnoreCase)) -or ($_.CommandLine -and $_.CommandLine.IndexOf($root,[StringComparison]::OrdinalIgnoreCase) -ge 0))}).Count){throw 'Cycle processes remain'}
$evidence=[IO.File]::ReadAllText("$root\refusal-evidence.json")|ConvertFrom-Json
if($evidence.run -cne $id -or $evidence.messageClassificationOnly -notin @('IntentPath','KnownSharingViolationNoFileName','Other')){throw 'Refusal classification differs'}
[pscustomobject]@{run=$id;success=$true;nativeStartRefusedWhileIntentWriteDenied=$true;messageClassification=$evidence.messageClassificationOnly;causalFileUnproven=[bool]$evidence.causalFileUnproven;oldServicePid=$baseline.servicePid;newServicePid=$svc.ProcessId;jobActiveAfter=$result.jobActiveAfter;intentUnchanged=$true;agentUnchanged=$true;manifestUnchanged=$true;rootRetained=$true;tasksRetained=$true;scope='Native start refusal while intent write was denied, and service restart; no upgrade, TUN, or power-loss proof'}|ConvertTo-Json -Compress
